use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/tmp/zopro-g2-tree-sdk";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let src=r.join("candidate");let base=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();for(p,h)in base["source_files_sha256"].as_object().unwrap(){let path=src.join(p);let actual=hash(&path);if actual!=h.as_str().unwrap(){changed.push(p.clone());}assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());pins.insert(path.display().to_string(),actual);}
 assert_eq!(changed,vec!["crates/zopro-core/src/msm.rs","crates/zopro-core/src/msm_affine.rs","crates/zopro-core/src/msm_affine/g2_phi.rs","crates/zopro-core/src/msm_affine/workspace.rs","crates/zopro-core/src/preparation.rs"]);
 for rel in ["crates/zopro-core/src/msm_affine/g2_prefix_tree.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{let p=src.join(rel);pins.insert(p.display().to_string(),hash(p));}for rel in ["setup.rs","design.md"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}
 let old=Path::new("/tmp/zopro-g2-tree-c7a/candidate-source/crates/zopro-core/src");let new=src.join("crates/zopro-core/src");
 for file in ["msm_affine/g2_prefix_tree.rs","msm.rs"]{let oldtext=fs::read_to_string(old.join(file)).unwrap();let newtext=fs::read_to_string(new.join(file)).unwrap();let bounds=if file=="msm.rs"{("pub(super) fn group_g2_prefix(","#[cfg(zopro_g2_prefix_tree)]")}else{("fn component(","pub(crate) fn probe(")};let a=oldtext.find(bounds.0).unwrap();let b=oldtext[a..].find(bounds.1).unwrap()+a;let oldbody=oldtext[a..b].trim();if file=="msm.rs"{let stop=newtext.find("#[cfg(all(zopro_g2_prefix_tree,zopro_resource_schedule,zopro_g2_prefix_records,zopro_g2_horner_buckets,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)))]\npub(crate) fn workspace_g2_prefix_groups").unwrap();let start=newtext.find(bounds.0).unwrap();assert_eq!(&newtext[start..stop].trim(),&oldbody);}else{let start=newtext.find(bounds.0).unwrap();let stop=newtext.find("fn eligible(").unwrap();assert_eq!(&newtext[start..stop].trim(),&oldbody);}}
 save(r.join("source-pins.json"),&json!(pins));save(r.join("implementation-audit.json"),&json!({"status":"pass","base_manifest_sha256":hash("/tmp/zopro-grouping-module/production-source-manifest.json"),"base_files":170,"unchanged_originals":165,"changed":changed,"new_module":"crates/zopro-core/src/msm_affine/g2_prefix_tree.rs","tree_math_byte_identical":true,"group_kernel_byte_identical":true,"production_sources_unchanged":true,"generic_tree_module_present":false,"adopted":false}));
 let mut p=read("/tmp/zopro-prefix-pool/native-plan.json");let s=serde_json::to_string(&p).unwrap().replace("/tmp/zopro-prefix-pool",R).replace("--cfg zopro_prefix_pool","--cfg zopro_g2_prefix_tree").replace("target-cpu=native","target-cpu=znver4");p=serde_json::from_str(&s).unwrap();p["environment"].as_object_mut().unwrap().remove("ZOPRO_CPU_PREFIX_POOL");p["environment"]["ZOPRO_CPU_G2_PREFIX_TREE"]=json!("1");p["source_pins"]=json!(r.join("source-pins.json"));
 for step in p["steps"].as_array_mut().unwrap(){if step["kind"]=="link-sdk"{step["rustc_flags"]=json!(["-O","-C","target-cpu=znver4","-C","lto=fat","-C","codegen-units=1"]);}if step["name"]=="on-core"{step["required_tests"]=json!(["msm_affine::g2_prefix_tree::tests::prefix_query_complete_curve_generator_oracles","msm_affine::g2_prefix_tree::tests::actual_size_prefix_matches_stream_and_generator","msm_affine::g2_prefix_tree::tests::wide_route_requires_explicit_kernel_configuration_and_supported_geometry","msm_affine::g2_prefix_tree::tests::denied_admission_preserves_canonical_words_for_stream_fallback","msm_affine::g2_prefix_tree::tests::accepted_admission_matches_stream_in_wide_pool","msm::g2_prefix_tree_tests::grouped_prefix_handles_signed_exceptions_odd_and_skewed_buckets"]);}}
 let flags=p["steps"][2]["environment"]["RUSTFLAGS"].as_str().unwrap().to_owned();for(name,rf)in[("portable",flags.replace("target-cpu=znver4","target-cpu=x86-64")),("no-ifma",format!("{flags} --cfg no_ifma"))]{p["steps"].as_array_mut().unwrap().push(json!({"kind":"command","name":format!("{name}-consumers"),"argv":["cargo","check","--manifest-path",src.join("Cargo.toml"),"--offline","--locked","--release","--lib","-p","zopro-core","-p","zopro-prover","-p","zopro-zolana"],"environment":{"CARGO_TARGET_DIR":r.join(format!("target-{name}")),"RUSTFLAGS":rf},"timeout_seconds":1200}));}
 save(r.join("native-plan.json"),&p);println!("Pinned{}inputs; tree math/kernel unchanged; native SDK and two consumer checks ready",pins.len());}
